#ifndef SCAMP_IMAGE_IO_HPP
#define SCAMP_IMAGE_IO_HPP

#include "image.hpp"
#include "wire_io.hpp"

#include <cstdio>
#include <string>
#include <vector>

/* ------------------------------------------------------------------ */
/* Internal text wire <-> image fields (shape is checked upstream)     */
/* ------------------------------------------------------------------ */

inline ip6_t read_ip(WireInput& in) {
    ip6_t ip;
    ip.hi = in.hex_fixed(16);
    ip.lo = in.hex_fixed(16);
    return ip;
}

inline ImageData image_read_wire(WireInput& in) {
    ImageData d;
    d.root.stage = static_cast<int>(in.integer());
    d.root.cell = in.uinteger();
    for (int which = 0; which < 2; ++which) {
        size_t n = in.uinteger();
        if (n > SCAMP_FRONT_LIMIT) throw std::runtime_error("front bound");
        std::vector<ImageFront> v(n);
        for (size_t i = 0; i < n; ++i) {
            v[i].key = in.hex_fixed(which ? 16 : 4);
            v[i].loc.stage = static_cast<int>(in.integer());
            v[i].loc.cell = in.uinteger();
        }
        if (which) d.front64.swap(v);
        else d.front16.swap(v);
    }
    for (int s = 0; s < RAM_NUM; ++s) d.cells[s] = in.uinteger();
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t n = in.uinteger();
        if (n > SCAMP_ROW_LIMIT) throw std::runtime_error("row bound");
        d.banks[s].resize(n);
        for (size_t i = 0; i < n; ++i) d.banks[s][i] = in.word();
    }
    size_t nb = in.uinteger();
    if (nb > SCAMP_BITMAP_LIMIT) throw std::runtime_error("bitmap bound");
    d.bitmaps.resize(nb);
    for (size_t i = 0; i < nb; ++i) d.bitmaps[i] = in.hex_fixed(16);
    size_t nn = in.uinteger();
    if (nn > SCAMP_NI_LIMIT) throw std::runtime_error("NI bound");
    d.nexthops.resize(nn);
    for (size_t i = 0; i < nn; ++i) d.nexthops[i] = in.uinteger();
    return d;
}

/* ------------------------------------------------------------------ */
/* JSON output helpers                                                 */
/* ------------------------------------------------------------------ */

inline void json_raw(std::string& o, const char* s) { o.append(s); }

inline void json_uint(std::string& o, uint64_t v) {
    char buf[24];
    int n = std::snprintf(buf, sizeof buf, "%llu", static_cast<unsigned long long>(v));
    o.append(buf, static_cast<size_t>(n));
}

inline void json_hex(std::string& o, uint64_t v, int width) {
    static const char* digits = "0123456789abcdef";
    size_t base = o.size();
    o.resize(base + static_cast<size_t>(width));
    for (int i = 0; i < width; ++i) {
        unsigned nib = static_cast<unsigned>((v >> (4 * (width - 1 - i))) & 0xFu);
        o[base + static_cast<size_t>(i)] = digits[nib];
    }
}

inline void json_word(std::string& o, const Row256& w) {
    static const char* digits = "0123456789abcdef";
    size_t base = o.size();
    o.resize(base + 64);
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= w[4 * i + b] ? (1u << b) : 0u;
        o[base + 63 - static_cast<size_t>(i)] = digits[v];
    }
}

inline void image_write_json(const ImageData& d, std::string& o) {
    json_raw(o, "{\"root\":");
    if (d.root.stage < 0) json_raw(o, "null");
    else {
        o.push_back('[');
        json_uint(o, static_cast<uint64_t>(d.root.stage));
        o.push_back(',');
        json_uint(o, d.root.cell);
        o.push_back(']');
    }
    for (int which = 0; which < 2; ++which) {
        json_raw(o, which ? ",\"front64\":[" : ",\"front16\":[");
        const std::vector<ImageFront>& v = which ? d.front64 : d.front16;
        for (size_t i = 0; i < v.size(); ++i) {
            if (i) o.push_back(',');
            o.push_back('[');
            o.push_back('"');
            json_hex(o, v[i].key, which ? 16 : 4);
            o.push_back('"');
            o.push_back(',');
            json_uint(o, static_cast<uint64_t>(v[i].loc.stage));
            o.push_back(',');
            json_uint(o, v[i].loc.cell);
            o.push_back(']');
        }
        o.push_back(']');
    }
    json_raw(o, ",\"cells\":[");
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) o.push_back(',');
        json_uint(o, d.cells[s]);
    }
    json_raw(o, "],\"banks\":[");
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) o.push_back(',');
        o.push_back('[');
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (i) o.push_back(',');
            o.push_back('"');
            json_word(o, d.banks[s][i]);
            o.push_back('"');
        }
        o.push_back(']');
    }
    json_raw(o, "],\"bitmaps\":[");
    for (size_t i = 0; i < d.bitmaps.size(); ++i) {
        if (i) o.push_back(',');
        o.push_back('"');
        json_hex(o, d.bitmaps[i], 16);
        o.push_back('"');
    }
    json_raw(o, "],\"nexthops\":[");
    for (size_t i = 0; i < d.nexthops.size(); ++i) {
        if (i) o.push_back(',');
        json_uint(o, d.nexthops[i]);
    }
    json_raw(o, "]}");
}

#endif /* SCAMP_IMAGE_IO_HPP */
