#include "fib.h"
#include "image.hpp"
#include "image_build.h"
#include "image_io.hpp"

#include <cstdio>
#include <cstdlib>
#include <stdexcept>
#include <string>
#include <vector>
#include <sys/wait.h>

namespace {

void write_answers(std::string& o, const std::vector<nexthop_t>& answers) {
    json_raw(o, "{\"answers\":[");
    for (size_t i = 0; i < answers.size(); ++i) {
        if (i) o.push_back(',');
        if (answers[i] == LPM_INVALID_NH) json_raw(o, "null");
        else json_uint(o, answers[i]);
    }
    json_raw(o, "],\"snapshots\":[");
}

} /* namespace */

int main() {
    try {
        WireInput in;
        unsigned cases = in.uinteger();
        if (cases > 2) throw std::runtime_error("case count");
        std::string out;
        out.reserve(1u << 16);
        json_raw(out, "{\"results\":[");
        for (unsigned c = 0; c < cases; ++c) {
            if (c) out.push_back(',');
            LiveFib live;
            MemoryImage loaded;
            std::vector<ImageData> saved;
            std::vector<nexthop_t> answers;
            std::vector<char> loads;

            unsigned count = in.uinteger();
            for (unsigned i = 0; i < count; ++i) {
                char op = in.op();
                if (op == 'P') {
                    ip6_t ip = read_ip(in);
                    unsigned len = in.uinteger();
                    unsigned hop = in.uinteger();
                    if (len > 128) throw std::runtime_error("prefix length");
                    if (hop > SCAMP_HOP_MAX) throw std::runtime_error("hop");
                    live.put(scamp_make128(ip.hi, ip.lo), static_cast<int>(len), hop);
                } else if (op == 'Q' || op == 'I') {
                    unsigned n = in.uinteger();
                    for (unsigned j = 0; j < n; ++j) {
                        ip6_t ip = read_ip(in);
                        if (op == 'Q') answers.push_back(live.lookup(scamp_make128(ip.hi, ip.lo)));
                        else answers.push_back(loaded.lookup(ip));
                    }
                } else if (op == 'S') {
                    std::vector<ScampPrefix> fib;
                    live.enumerate(fib);
                    saved.push_back(build_image(fib));
                } else if (op == 'R') {
                    unsigned id = in.uinteger();
                    if (id >= saved.size()) throw std::runtime_error("saved index");
                    loads.push_back(loaded.load(saved[id]) ? 1 : 0);
                } else if (op == 'L') {
                    ImageData d = image_read_wire(in);
                    loads.push_back(loaded.load(d) ? 1 : 0);
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }

            write_answers(out, answers);
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) out.push_back(',');
                image_write_json(saved[i], out);
            }
            json_raw(out, "],\"loads\":[");
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) out.push_back(',');
                json_raw(out, loads[i] ? "true" : "false");
            }
            json_raw(out, "]}");
        }
        json_raw(out, "]}\n");
        if (std::fwrite(out.data(), 1, out.size(), stdout) != out.size())
            throw std::runtime_error("output write");
        std::fflush(stdout);
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status = 0;
            pid_t pid = static_cast<pid_t>(std::strtol(feed, nullptr, 10));
            if (pid > 0) waitpid(pid, &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "%s\n", e.what());
        return 1;
    }
}
